            f"<b>Итого:</b> {total_pnl:+.2f} USDT за {total_n} сделок",
            "<i>Аналог Freqtrade /daily — по календарным дням местного времени.</i>",
        ]
    )
    return "\n".join(lines)


def build_daily_pnl_report(
    journal_path: Path,
    days: int = 7,
    *,
    timezone_offset: int = 3,
) -> str:
    """Дневной PnL для кнопки Telegram «📅 По дням»."""
