            f"Средн. PnL (net): <b>{avg:+.3f}%</b> | TP: {stats.get('tp_hits', 0)} | "
            f"SL: {stats.get('sl_hits', 0)} | open: {stats.get('still_open', 0)}",
            f"Комиссия (ср.): {stats.get('avg_fee_pct', 0):.4f}% round-trip",
            "",
        ]
