                f"<b>Последний прогон:</b> +{tested} симуляций ({oc_txt})"
            )
        tunes = last_run.get("filter_tunes_applied")
        if tunes is not None:
            lines.append(f"Подстройка фильтров: {tunes}")

    total_lines = sum(1 for _ in self.results_path.open(encoding="utf-8")) if self.results_path.exists() else 0
    lines.append(f"\n<i>Всего в архиве: {total_lines} записей → {self.results_path.name}</i>")
