# Копирование ~/.hermes на VPS (без тяжёлого lsp/node_modules)
# Использование: .\sync-to-vps.ps1 -Server root@ВАШ_IP
param(
    [Parameter(Mandatory = $true)]
    [string]$Server,
    [string]$LocalDir = "$env:USERPROFILE\.vscode\.hermes",
    [string]$RemoteDir = "/root/.hermes"
)

$ErrorActionPreference = "Stop"
if (-not (Test-Path $LocalDir)) { throw "Нет папки: $LocalDir" }

Write-Host "==> rsync/scp Hermes -> $Server`:$RemoteDir"

# tar exclude — быстрее чем scp всего дерева на Windows без rsync
$temp = Join-Path $env:TEMP "hermes-sync-$(Get-Date -Format 'yyyyMMddHHmmss').tar.gz"
Push-Location $LocalDir
try {
    if (Get-Command tar -ErrorAction SilentlyContinue) {
        tar --exclude="lsp/node_modules" --exclude="**/__pycache__" -czf $temp .
        scp $temp "${Server}:/tmp/hermes-sync.tar.gz"
        ssh $Server "mkdir -p $RemoteDir && tar -xzf /tmp/hermes-sync.tar.gz -C $RemoteDir && rm /tmp/hermes-sync.tar.gz && chmod +x $RemoteDir/scripts/*.sh 2>/dev/null; chmod 600 $RemoteDir/.env 2>/dev/null; true"
    } else {
        Write-Warning "tar не найден — копируем только ключевые файлы через scp"
        $files = @(
            "config.yaml", "SOUL.md", "strategy-goals.yaml", ".env",
            "skills", "scripts", "prompts"
        )
        ssh $Server "mkdir -p $RemoteDir"
        foreach ($f in $files) {
            $src = Join-Path $LocalDir $f
            if (Test-Path $src) {
                scp -r $src "${Server}:${RemoteDir}/"
            }
        }
    }
} finally {
    Pop-Location
    if (Test-Path $temp) { Remove-Item $temp -Force }
}

